/bin/zsh -lc "python -c 'import pandas as pd,numpy as np; d=pd.read_csv(\"data/freshwater_fish_basins.csv\"); y=d.diversity.to_numpy(float); x=np.c_[np.ones(len(d)),np.log(d.area),d.bio1,d.bio12/1000]; b=np.linalg.lstsq(x,np.log(y+.5),rcond=None)[0]; f=lambda q: np.sum(np.exp(x@q)-y*(x@q));
for it in range(100):
 e=x@b; m=np.exp(e); gr=x.T@(m-y); h=x.T@(m[:,None]*x); step=-np.linalg.solve(h,gr); old=f(b); a=1
 while f(b+a*step)>old+1e-4*a*gr@step: a*=.5
 b=b+a*step
 if it%5==0: print(it,b,np.max(np.abs(gr)),a)
 if np.max(np.abs(gr))<1e-7: break
print(\"final\",b,gr,f(b))'"

